// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    MockGlpManager glpManager;

    function setUp() public {
        c = new DnGmxBatchingManager();
        glpManager = new MockGlpManager();
        // initialize via low-level call to avoid interface-name ambiguity
        bytes memory data = abi.encodeWithSignature(
            "initialize(address,address,address,address,address,address)",
            address(1),
            address(2),
            address(3),
            address(glpManager),
            address(4),
            address(this)
        );
        (bool ok, ) = address(c).call(data);
        require(ok, "init failed");
    }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        address currentOwner = c.owner();
        vm.prank(currentOwner);
        c.transferOwnership(newOwner);
        assertTrue(c.owner() == newOwner);
    }
}

contract MockGlpManager {
    function vault() external pure returns (address) {
        return address(1);
    }
}
